#!/bin/sh
# Print the three most frequent IP addresses from access.log, most frequent
# first.  Ties are broken by first appearance in the log.

awk '
{
    if (!($1 in first)) {
        first[$1] = NR
    }
    count[$1]++
}
END {
    for (ip in count) {
        print count[ip], first[ip], ip
    }
}
' access.log \
    | sort -k1,1nr -k2,2n \
    | head -n 3 \
    | awk '{print $3}'
